import numpy as np
from collections import defaultdict
from typing import List, Dict, Any, Tuple
import math
import random

# --- Resources and Components ---
RESOURCES = {
    "wood": {"cost": 1},
    "stone": {"cost": 2},
    "metal": {"cost": 3},
}

COMPONENTS = {
    "foundation": {"resources": {"stone": 2, "wood": 1}, "craft_time": 2},
    "wall_segment": {"resources": {"wood": 2, "metal": 1}, "craft_time": 3},
    "roof_panel": {"resources": {"wood": 3}, "craft_time": 1},
    "door_frame": {"resources": {"wood": 1, "metal": 2}, "craft_time": 2}, 
}

# --- Building Structure ---
BUILDING_PLAN = {
    "house_phase1": [
        ("foundation_1", []), 
        ("foundation_2", []),
        ("wall_segment_1", ["foundation_1"]), 
        ("wall_segment_2", ["foundation_2"]),
    ],
    "house_phase2": [ 
        ("roof_panel_1", ["wall_segment_1", "wall_segment_2"]), 
        ("door_frame_1", ["wall_segment_1"]), 
    ]
}

class Resource:
    def __init__(self, resource_id: str, amount: int):
        self.id = resource_id
        self.amount = amount

class Component:
    def __init__(self, component_id: str, blueprint: Dict[str, Any]):
        self.id = component_id
        self.resources_needed = blueprint["resources"].copy()
        self.craft_time = blueprint["craft_time"]
        self.current_craft_time = 0
        self.ready_for_assembly = False

    def add_craft_time(self, amount: int):
        if not self.ready_for_assembly:
            self.current_craft_time += amount
            if self.current_craft_time >= self.craft_time:
                self.ready_for_assembly = True

class BuildingComponent:
    def __init__(self, component_id: str, dependencies: List[str]):
        self.id = component_id
        self.dependencies = dependencies
        self.crafted_ready = False 
        self.assembled = False

    def check_crafted_ready(self, world_components: Dict[str, Component]):
        base_comp_id = '_'.join(self.id.split('_')[:-1])
        if base_comp_id in world_components and world_components[base_comp_id].ready_for_assembly:
            self.crafted_ready = True

    def check_dependencies(self, global_assembled_status: Dict[str, bool]) -> bool:
        return all(global_assembled_status.get(dep, False) for dep in self.dependencies)

    def assemble(self):
        if self.crafted_ready and not self.assembled:
            self.assembled = True

class ConstructionAgent:
    def __init__(self, agent_id: str, all_agent_ids: List[str], num_agents: int, learning_rate: float = 0.35, epsilon_start: float = 0.1, epsilon_end: float = 0.005, mutation_rate: float = 0.05, preferred_action: str = None, inherited_strategy: Dict[str, Any] = None, all_possible_actions_global: List[str] = None): 
        self.agent_id = agent_id
        self.all_agent_ids = all_agent_ids
        self.num_agents = num_agents
        self.total_reward = 0
        self.learning_rate = learning_rate
        self.epsilon_start = epsilon_start
        self.epsilon_end = epsilon_end
        self.mutation_rate = mutation_rate
        self.preferred_action = preferred_action

        self.action_strategy = defaultdict(lambda: {'success': 1, 'attempts': 2, 'value_est': 0.1}) 
        if all_possible_actions_global:
            for action_key in all_possible_actions_global:
                self.action_strategy[action_key]['success'] = 1
                self.action_strategy[action_key]['attempts'] = 2
                self.action_strategy[action_key]['value_est'] = 0.1

        if inherited_strategy:
            for action_key, strategy_data in inherited_strategy.items():
                self.action_strategy[action_key]['success'] = strategy_data.get('success', 1)
                self.action_strategy[action_key]['attempts'] = strategy_data.get('attempts', 2)
                self.action_strategy[action_key]['value_est'] = np.clip(
                    strategy_data.get('value_est', 0.5) + np.random.uniform(-0.02, 0.02), 0, 1) 
        elif self.preferred_action:
            self.action_strategy[self.preferred_action]['value_est'] = 0.98 

        self.reputations = {aid: 0.5 for aid in all_agent_ids if aid != agent_id}
        if inherited_strategy and 'reputations' in inherited_strategy: 
            pass 

        self.action_history_window = 20
        self.recent_actions = defaultdict(lambda: [])
        self.specialization_index = 0.0
        self.most_specialized_action = "None"

        self.current_resources = {} 
        for res_id in RESOURCES.keys():
            self.current_resources[res_id] = 0

        print(f"Construction Agent {self.agent_id} initialized (LR: {self.learning_rate:.2f}, M: {self.mutation_rate:.2f}, Pref: {self.preferred_action}, Inherited: {bool(inherited_strategy)}).")

    def _get_epsilon(self, current_round: int, total_rounds: int) -> float:
        decay_rate = (self.epsilon_start - self.epsilon_end) / total_rounds
        return max(self.epsilon_end, self.epsilon_start - decay_rate * current_round)

    def choose_action(self, all_possible_action_keys_global: List[str], current_round: int, total_rounds: int,
                      env_world_resources: Dict[str, Resource], env_world_components: Dict[str, Component],
                      env_building_status: Dict[str, BuildingComponent], env_completed_components_history: Dict[str, bool]) -> Tuple[str, str]:
        current_epsilon = self._get_epsilon(current_round, total_rounds)

        action_type = "gather" 
        target_id = None

        critical_actions = []
        unassembled_current_phase = [bc_id for bc_id, bc in env_building_status.items() if not bc.assembled]

        for bc_id in unassembled_current_phase:
            bc = env_building_status[bc_id]
            if bc.crafted_ready and bc.check_dependencies(env_completed_components_history):
                critical_actions.append(("assemble", bc_id))

        if not critical_actions: 
            needed_base_components = set()
            for bc_id in unassembled_current_phase:
                base_comp_id = '_'.join(bc_id.split('_')[:-1]) 
                if base_comp_id in COMPONENTS and not env_world_components[base_comp_id].ready_for_assembly:
                    needed_base_components.add(base_comp_id)

            for base_comp_id in needed_base_components:
                can_craft = True
                for res_id, needed in COMPONENTS[base_comp_id]["resources"].items():
                    if self.current_resources.get(res_id, 0) < needed:
                        can_craft = False
                        break
                if can_craft:
                    critical_actions.append(("craft", base_comp_id))

        if not critical_actions: 
            needed_resources_for_critical_craft = defaultdict(int)
            for base_comp_id in needed_base_components:
                for res_id, amount in COMPONENTS[base_comp_id]["resources"].items():
                    needed_resources_for_critical_craft[res_id] += amount

            for res_id, amount_needed in needed_resources_for_critical_craft.items():
                if self.current_resources.get(res_id, 0) < amount_needed and env_world_resources[res_id].amount > 0:
                    critical_actions.append(("gather", res_id))

        if critical_actions and np.random.rand() >= current_epsilon:
            action_values = {}
            for action, target in critical_actions:
                action_key = f"{action}_{target}"
                action_values[action_key] = self.action_strategy[action_key]['value_est']

            chosen_action_key = max(action_values, key=action_values.get)
            parts = chosen_action_key.split('_')
            action_type = parts[0]
            target_id = '_'.join(parts[1:])
        else: 
            action_options = []
            for res_id in RESOURCES.keys():
                if env_world_resources[res_id].amount > 0:
                    action_options.append(("gather", res_id))
            for comp_id in COMPONENTS.keys():
                if not env_world_components[comp_id].ready_for_assembly and \
                   all(self.current_resources.get(res_id, 0) >= needed for res_id, needed in COMPONENTS[comp_id]["resources"].items()):
                    action_options.append(("craft", comp_id))
            for bc_id in env_building_status:
                bc = env_building_status[bc_id]
                if not bc.assembled and bc.crafted_ready and bc.check_dependencies(env_completed_components_history):
                    action_options.append(("assemble", bc_id))

            if action_options:
                if np.random.rand() < current_epsilon: 
                    action_type, target_id = random.choice(action_options)
                else: 
                    action_values = {}
                    for action, target in action_options:
                        action_key = f"{action}_{target}"
                        action_values[action_key] = self.action_strategy[action_key]['value_est']

                    chosen_action_key = max(action_values, key=action_values.get)
                    parts = chosen_action_key.split('_')
                    action_type = parts[0]
                    target_id = '_'.join(parts[1:])
            else: 
                action_type = "gather"
                target_id = np.random.choice(list(RESOURCES.keys()))

        return action_type, target_id

    def update_learning(self, chosen_action: Tuple[str, str], collective_round_reward: float, world_components: Dict[str, Component], current_max_possible_collective_reward: float, current_round: int):
        action_key = f"{chosen_action[0]}_{chosen_action[1]}"

        reward_signal = collective_round_reward / current_max_possible_collective_reward if current_max_possible_collective_reward > 0 else 0.0

        self.action_strategy[action_key]['attempts'] += 1 
        self.action_strategy[action_key]['value_est'] = np.clip(
            (1 - self.learning_rate) * self.action_strategy[action_key]['value_est'] + \
            self.learning_rate * reward_signal, 0, 1)

    def update_reputation_from_round_outcome(self, collective_round_reward: float, max_possible_collective_reward_this_round: float):
        performance_score = collective_round_reward / max_possible_collective_reward_this_round if max_possible_collective_reward_this_round > 0 else 0.0

        for aid in self.reputations.keys():
            self.reputations[aid] = np.clip(
                (1 - self.learning_rate) * self.reputations[aid] + \
                self.learning_rate * performance_score, 0, 1)

    def record_actions(self, action_type: str, target_id: str):
        action_key = f"{action_type}_{target_id}"
        self.recent_actions[action_key].append(1) 
        if len(self.recent_actions[action_key]) > self.action_history_window:
            self.recent_actions[action_key].pop(0)

    def calculate_specialization_index(self, all_possible_action_keys_global: List[str]) -> Tuple[str, float]:
        total_actions_in_window = sum(sum(counts) for counts in self.recent_actions.values())
        if total_actions_in_window == 0:
            self.specialization_index = 0.0
            self.most_specialized_action = "None"
            return "None", 0.0

        action_sums = {ak: sum(counts) for ak, counts in self.recent_actions.items()}

        proportions = np.array([action_sums.get(ak, 0) / total_actions_in_window for ak in all_possible_action_keys_global]) 

        positive_proportions = proportions[proportions > 0]

        if len(positive_proportions) > 1:
            entropy = -np.sum(positive_proportions * np.log2(positive_proportions))
            max_entropy = math.log2(len(positive_proportions)) if len(positive_proportions) > 0 else 0.0
            specialization_index = 1 - (entropy / max_entropy) if max_entropy > 0 else 0.0
        else:
            specialization_index = 1.0 if len(positive_proportions) == 1 else 0.0

        most_specialized_action = max(action_sums, key=action_sums.get) if action_sums else "None"

        self.specialization_index = specialization_index
        self.most_specialized_action = most_specialized_action
        return most_specialized_action, specialization_index

    def consider_strategy_adoption(self, all_agents: Dict[str, 'ConstructionAgent'], current_round: int, total_rounds: int,
                                   adoption_threshold_self_reward_factor: float = 0.5, 
                                   adoption_threshold_other_rep: float = 0.5, 
                                   top_n_percent_mentors: float = 0.25, max_possible_collective_reward_per_round: float = 0):

        expected_total_reward_for_current_round = max_possible_collective_reward_per_round * (current_round + 1)
        dynamic_self_reward_threshold = expected_total_reward_for_current_round * adoption_threshold_self_reward_factor

        if self.total_reward < dynamic_self_reward_threshold: 
            sorted_agents = sorted(all_agents.values(), key=lambda a: a.total_reward, reverse=True)
            num_top_mentors = max(1, int(len(self.all_agent_ids) * top_n_percent_mentors))

            potential_mentors = []
            for mentor_candidate in sorted_agents[:num_top_mentors]: 
                if mentor_candidate.agent_id == self.agent_id: continue

                rep_threshold = max(adoption_threshold_other_rep, 0.2) 
                if self.reputations.get(mentor_candidate.agent_id, 0.0) >= rep_threshold: 
                    potential_mentors.append(mentor_candidate)

            if potential_mentors:
                mentor = max(potential_mentors, key=lambda a: a.total_reward)

                for action_key in set(self.action_strategy.keys()).union(mentor.action_strategy.keys()):
                    if action_key in mentor.action_strategy:
                        self.action_strategy[action_key]['success'] = mentor.action_strategy[action_key].get('success', 1)
                        self.action_strategy[action_key]['attempts'] = mentor.action_strategy[action_key].get('attempts', 2)
                        self.action_strategy[action_key]['value_est'] = mentor.action_strategy[action_key].get('value_est', 0.5)
                    elif action_key in self.action_strategy: 
                        pass 
                    else: 
                        self.action_strategy[action_key] = {'success': 1, 'attempts': 2, 'value_est': 0.5}

                if np.random.rand() < self.mutation_rate:
                    for action_key in self.action_strategy.keys():
                        self.action_strategy[action_key]['value_est'] = np.clip(self.action_strategy[action_key]['value_est'] + np.random.uniform(-0.1, 0.1), 0, 1)

                self.epsilon_start = 0.08 

class CooperativeBuildingEnvironment:
    def __init__(self, num_agents: int, total_resource_capacity: int = 400):
        self.num_agents = num_agents
        self.total_resource_capacity = total_resource_capacity
        self.world_resources: Dict[str, Resource] = {}
        self.world_components: Dict[str, Component] = {} 
        self.building_status: Dict[str, BuildingComponent] = {} 
        self.completed_components_history: Dict[str, bool] = {} 
        self.current_building_phase = "house_phase1" 

        for res_id in RESOURCES.keys():
            self.world_resources[res_id] = Resource(res_id, amount=self.total_resource_capacity // len(RESOURCES))

        for comp_id, blueprint in COMPONENTS.items():
            self.world_components[comp_id] = Component(comp_id, blueprint)

        self._initialize_building_phase(self.current_building_phase)

        self.max_possible_collective_reward_per_round = 3000 

        print(f"Environment initialized for {num_agents} agents for building task (Phase: {self.current_building_phase}).")

    def _initialize_building_phase(self, phase_name: str):
        new_phase_building_status = {}
        for bc_id, deps in BUILDING_PLAN[phase_name]:
            new_phase_building_status[bc_id] = BuildingComponent(bc_id, deps)
        self.building_status = new_phase_building_status 

        print(f"  Initialized Building Phase: {phase_name}")

    def _check_phase_complete(self) -> bool:
        current_phase_component_ids = [comp_id for comp_id, _ in BUILDING_PLAN[self.current_building_phase]]

        if not all(comp_id in self.building_status for comp_id in current_phase_component_ids):
            return False 

        return all(self.building_status[bc_id].assembled for bc_id in current_phase_component_ids)

    def transition_phase(self):
        if self._check_phase_complete():
            if self.current_building_phase == "house_phase1":
                print("\n--- Phase 1 Complete! Transitioning to Phase 2 ---")
                self.current_building_phase = "house_phase2"
                self._initialize_building_phase(self.current_building_phase)
                return True
            elif self.current_building_phase == "house_phase2":
                print("\n--- All Building Phases Complete! ---")
                return True
        return False

    def introduce_dynamic_event(self, current_round: int):
        # Re-introducing dynamic events for this experiment
        if current_round == 500: # Example event: Wood becomes scarce
            self.world_resources["wood"].amount = 5
            print(f"\n--- Dynamic Event at Round {current_round}: Wood Scarcity! ---")
        elif current_round == 1000: # Example event: A wall segment is damaged and needs re-crafting/re-assembling
            # Make sure 'wall_segment' (the craftable component) is not ready
            if self.world_components['wall_segment'].ready_for_assembly:
                print(f"\n--- Dynamic Event at Round {current_round}: Wall Segment Crafting Reset! ---")
                self.world_components['wall_segment'].ready_for_assembly = False
                self.world_components['wall_segment'].current_craft_time = 0

            # If wall_segment_1 was assembled globally, mark it as unassembled and remove from history
            if self.completed_components_history.get("wall_segment_1", False):
                print(f"    - Global BuildingComponent 'wall_segment_1' marked as unassembled.")
                self.completed_components_history["wall_segment_1"] = False
                # Any dependent components will also become unassembled due to unmet dependencies in the current building_status
                for bc_id, bc in self.building_status.items():
                    if "wall_segment_1" in bc.dependencies and bc.assembled:
                        bc.assembled = False
                        print(f"    - {bc_id} (dependent on wall_segment_1) also became unassembled.")
                        self.completed_components_history[bc_id] = False # Reflect in global history too

    def get_collective_reward(self) -> float:
        total_components_in_current_phase = len(BUILDING_PLAN[self.current_building_phase])
        if total_components_in_current_phase == 0: return 0

        reward = 0.0
        for bc_id, bc in self.building_status.items():
            if bc.assembled:
                reward += (self.max_possible_collective_reward_per_round * 0.75 / total_components_in_current_phase) 

        if self._check_phase_complete():
            reward += (self.max_possible_collective_reward_per_round * 0.25) 

        return reward

    def process_actions(self, agent_actions: Dict[str, Tuple[str, str]], agents_dict: Dict[str, ConstructionAgent]) -> float:
        resource_gains = defaultdict(int)
        craft_progress = defaultdict(int)
        assemble_attempts = defaultdict(lambda: [])

        for agent_id, (action_type, target_id) in agent_actions.items():
            agent = agents_dict[agent_id]
            if action_type == "gather":
                if target_id in self.world_resources and self.world_resources[target_id].amount > 0:
                    agent.current_resources[target_id] += 1
                    self.world_resources[target_id].amount -= 1
            elif action_type == "craft":
                if target_id in self.world_components:
                    can_craft = True
                    for res_id, needed in COMPONENTS[target_id]["resources"].items():
                        if agent.current_resources.get(res_id, 0) < needed:
                            can_craft = False
                            break
                    if can_craft and not self.world_components[target_id].ready_for_assembly:
                        for res_id, needed in COMPONENTS[target_id]["resources"].items():
                            agent.current_resources[res_id] -= needed
                        craft_progress[target_id] += 1 
            elif action_type == "assemble":
                if target_id in self.building_status and not self.building_status[target_id].assembled:
                    assemble_attempts[target_id].append(agent_id) 

        for comp_id, progress in craft_progress.items():
            self.world_components[comp_id].add_craft_time(progress)

        for bc_id, bc in self.building_status.items():
            bc.check_crafted_ready(self.world_components)

        for bc_id, agent_ids in assemble_attempts.items():
            bc = self.building_status[bc_id]
            if bc.crafted_ready and bc.check_dependencies(self.completed_components_history): 
                if not bc.assembled: 
                    bc.assemble()
                    self.completed_components_history[bc_id] = True 

        return self.get_collective_reward()

    def get_all_possible_action_keys(self) -> List[str]: 
        actions = []
        for res_id in RESOURCES.keys():
            actions.append(f"gather_{res_id}")
        for comp_id in COMPONENTS.keys():
            actions.append(f"craft_{comp_id}")
        for bc_id in self.building_status.keys(): 
            actions.append(f"assemble_{bc_id}")
        return actions

    def get_all_possible_action_keys_global(self) -> List[str]: 
        actions = []
        for res_id in RESOURCES.keys():
            actions.append(f"gather_{res_id}")
        for comp_id in COMPONENTS.keys():
            actions.append(f"craft_{comp_id}")

        all_bc_ids_defined = set()
        for phase_name in BUILDING_PLAN:
            for bc_id, _ in BUILDING_PLAN[phase_name]:
                all_bc_ids_defined.add(bc_id)
        for bc_id in all_bc_ids_defined:
            actions.append(f"assemble_{bc_id}")
        return actions

# --- Simulation Setup ---
NUM_AGENTS = 7 # Increased number of agents
NUM_ROUNDS = 2000 
TOTAL_RESOURCE_CAPACITY = 400 

all_agent_ids = [f"Agent_{i+1}" for i in range(NUM_AGENTS)]

# ANCESTOR STRATEGY FROM Eval ID: 461 (Simulated extraction - final state of Generation 4)
ancestor_strategies_from_eval461 = {
    "Agent_1": {"gather_wood": {'value_est': 0.98}, "craft_foundation":{'value_est':0.4}, "assemble_wall_segment_1":{'value_est':0.4}},
    "Agent_2": {"gather_metal": {'value_est': 0.98}, "craft_wall_segment":{'value_est':0.4}},
