current_generation_id = 5 # This is now Generation 5

agents_dict = {}

for i, aid in enumerate(all_agent_ids):
    ancestor_agent_id = f"Agent_{i+1}" 
    inherited_strategy_for_descendant = full_ancestor_strategies.get(ancestor_agent_id)

    agents_dict[aid] = ConstructionAgent(aid, all_agent_ids, NUM_AGENTS, 
                                         learning_rate=0.35, epsilon_start=0.1, epsilon_end=0.005, mutation_rate=0.05, 
                                         inherited_strategy=inherited_strategy_for_descendant,
                                         all_possible_actions_global=all_possible_base_actions_global) 

env = CooperativeBuildingEnvironment(NUM_AGENTS, total_resource_capacity=TOTAL_RESOURCE_CAPACITY)
all_possible_action_keys_global = env.get_all_possible_action_keys_global() 

print(f"\n--- Starting {NUM_ROUNDS} Rounds of Transgenerational Building Task (Generation {current_generation_id}, Agents: {NUM_AGENTS}) ---")

for i in range(NUM_ROUNDS):
