        )

    collective_round_reward = env.process_actions(agent_actions_this_round, agents_dict)

    for agent_id in all_agent_ids:
        agent = agents_dict[agent_id]
        agent.total_reward += collective_round_reward / NUM_AGENTS 

        action_key = f"{agent_actions_this_round[agent_id][0]}_{agent_actions_this_round[agent_id][1]}"

        reward_signal = collective_round_reward / env.max_possible_collective_reward_per_round if env.max_possible_collective_reward_per_round > 0 else 0.0

        agent.action_strategy[action_key]['attempts'] += 1 
        agent.action_strategy[action_key]['value_est'] = np.clip(
            (1 - agent.learning_rate) * agent.action_strategy[action_key]['value_est'] + \
            agent.learning_rate * reward_signal, 0, 1)

        performance_score = collective_round_reward / env.max_possible_collective_reward_per_round if env.max_possible_collective_reward_per_round > 0 else 0.0

        for aid_rep in agent.reputations.keys(): 
            agent.reputations[aid_rep] = np.clip(
                (1 - agent.learning_rate) * agent.reputations[aid_rep] + \
                agent.learning_rate * performance_score, 0, 1)

        agent.record_actions(agent_actions_this_round[agent_id][0], agent_actions_this_round[agent_id][1])
        agent.calculate_specialization_index(all_possible_action_keys_global) 

